/// <summary>
/// MPJ_33690_PurchaseOrderChangeService Purchase Order service Contract
/// </summary>
[DataContractAttribute('purchaseOrderRequest')]
class METPurchaseOrderServiceContract
{
    DataAreaId                                  dataAreaId;
    string20                                    type;
    PurchId                                     purchaseOrderNumber;
    string20                                    poeDIPOAMsg;
    string10                                    metPOEDIFAMsg;
    METPOYardDAppointmentStartDateTime          metPOYardDAppointmentStartDateTime;
    METPOYardDAppointmentEndDateTime            metPOYardDAppointmentEndDateTime;
    METPOYardDAppointmentID                     metAppointmentID;
    PurchLineDlvDate                            confirmedDeliveryDate;
    list                                        linesContract;

}

